{
  "title": "Qual dose de cefazolina preparar?",
  "setting": "Plantão na Clínica Ipê",
  "mission": "Confira o peso, a prescrição e o plano terapêutico para decidir **qual dose pode ser administrada com segurança**. Se houver divergência, esclareça-a antes de preparar o medicamento.",
  "deadline": "Dose prevista para as 14h; esclarecer a divergência antes de administrar.",
  "panels": [
    {
      "title": "Dose das 14h",
      "metrics": [
        {
          "label": "Peso aferido hoje",
          "value": "18 kg",
          "note": null
        },
        {
          "label": "Peso no registro anterior",
          "value": "16 kg",
          "note": null
        },
        {
          "label": "Prescrição atual",
          "value": "400 mg IV a cada 8 h",
          "note": "Cefazolina"
        },
        {
          "label": "Plano terapêutico",
          "value": "25 mg/kg/dose IV a cada 8 h",
          "note": "Registrado para este atendimento"
        }
      ],
      "note": "A dose ainda não foi administrada. O protocolo da clínica exige dupla checagem independente antes da administração."
    }
  ],
  "team": [
    {
      "id": "enfermeira",
      "role": "Enfermeira de referência",
      "expertise": "Confere o cálculo, a prescrição e a checagem independente.",
      "ai": false
    },
    {
      "id": "medico",
      "role": "Médico plantonista",
      "expertise": "Reavalia o plano terapêutico e altera a prescrição quando necessário.",
      "ai": false
    },
    {
      "id": "farmacia",
      "role": "Farmacêutica clínica",
      "expertise": "Confere a apresentação dispensada e sua concentração.",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "seguranca",
      "label": "Segurança da dose",
      "start": 55,
      "goodWhen": "high"
    },
    {
      "id": "horario",
      "label": "Chance de cumprir o horário",
      "start": 65,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "calculo",
      "name": "Calcular dose por peso",
      "practice": "Calcule 25 mg/kg/dose para 18 kg e converta o resultado em volume usando 100 mg/mL."
    },
    {
      "id": "conferencia",
      "name": "Conferir a prescrição",
      "practice": "Compare uma prescrição com o peso atual, o plano registrado, a via e o rótulo antes de preparar a dose."
    },
    {
      "id": "comunicacao",
      "name": "Comunicar uma dúvida ao médico",
      "practice": "Resuma em uma frase a divergência entre peso atual, dose calculada e prescrição, e peça confirmação."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "enfermeira",
          "text": "A prescrição foi feita quando constavam 16 kg. O peso de hoje é 18 kg; confira a conta e a via antes de separar a cefazolina."
        },
        {
          "from": "farmacia",
          "text": "Posso conferir a apresentação dispensada quando a dose estiver esclarecida."
        }
      ],
      "prompt": "Qual é seu primeiro passo?",
      "choices": [
        {
          "id": "calcular-conferir",
          "text": "Calcular com 18 kg e comparar o resultado com a prescrição e a via registrada.",
          "quality": "strong",
          "replies": [
            {
              "from": "enfermeira",
              "text": "18 kg × 25 mg/kg/dose = 450 mg por dose IV. A prescrição ainda indica 400 mg IV: a via confere, mas a dose precisa ser esclarecida."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": 15
            },
            {
              "meter": "horario",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "calculo",
              "kind": "good",
              "text": "Você usou o peso atual e chegou a 450 mg por dose.",
              "example": null
            },
            {
              "skill": "conferencia",
              "kind": "good",
              "text": "Você comparou o cálculo com a dose prescrita e confirmou que a via registrada é IV.",
              "example": null
            }
          ],
          "next": "esclarecer"
        },
        {
          "id": "calcular-sozinho",
          "text": "Calcular 450 mg com o peso atual, mas deixar a conferência da prescrição para depois.",
          "quality": "fair",
          "replies": [
            {
              "from": "enfermeira",
              "text": "A conta dá 450 mg. Antes de preparar, compare esse valor com os 400 mg prescritos e confira a via."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": 5
            },
            {
              "meter": "horario",
              "change": 0
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "conferencia",
              "kind": "improve",
              "text": "O cálculo isolado não resolve a divergência com a prescrição vigente. Faça a comparação antes do preparo.",
              "example": null
            }
          ],
          "next": "esclarecer"
        },
        {
          "id": "seguir-registro",
          "text": "Tomar os 400 mg prescritos como referência e perguntar à {{enfermeira}} se o novo peso muda a dose.",
          "quality": "weak",
          "replies": [
            {
              "from": "enfermeira",
              "text": "Boa pergunta. Com 18 kg, o plano registrado resulta em 450 mg por dose, não 400 mg. Precisamos esclarecer a prescrição antes de preparar."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": -5
            },
            {
              "meter": "horario",
              "change": 0
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "calculo",
              "kind": "improve",
              "text": "Pedir ajuda manteve a dúvida aberta, mas vale fazer a conta com o peso aferido hoje antes de tomar a dose antiga como referência.",
              "example": null
            }
          ],
          "next": "esclarecer"
        }
      ]
    },
    {
      "id": "esclarecer",
      "messages": [
        {
          "from": "enfermeira",
          "text": "Temos 450 mg pelo plano e 400 mg na prescrição. Não prepare nem administre enquanto a dose estiver divergente."
        }
      ],
      "prompt": "Como você busca uma decisão para a dose das 14h?",
      "choices": [
        {
          "id": "consultar-farmacia",
          "text": "Pedir à {{farmacia}} que confira a divergência e solicite a reavaliação da prescrição.",
          "quality": "fair",
          "replies": [
            {
              "from": "farmacia",
              "text": "Confirmo a diferença entre o cálculo e a prescrição. Vou levar peso, plano e dose ao {{medico}}; não posso alterá-la por conta própria."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": 10
            },
            {
              "meter": "horario",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "comunicacao",
              "kind": "good",
              "text": "Você buscou apoio sem tratar a conferência da farmácia como autorização para mudar a prescrição.",
              "example": null
            },
            {
              "skill": "comunicacao",
              "kind": "improve",
              "text": "Neste plantão, comunicar diretamente a divergência ao prescritor pode encurtar a espera.",
              "example": "“O peso atual é 18 kg; o plano resulta em 450 mg IV, mas constam 400 mg IV. Pode reavaliar a prescrição?”"
            }
          ],
          "next": "preparar"
        },
        {
          "id": "relatar-dados",
          "text": "Informar ao {{medico}} peso atual, cálculo, dose prescrita e via; aguardar a prescrição atualizada.",
          "quality": "strong",
          "replies": [
            {
              "from": "medico",
              "text": "Obrigado pelos dados. Vou conferir o plano e atualizar a prescrição antes do preparo."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": 15
            },
            {
              "meter": "horario",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "comunicacao",
              "kind": "good",
              "text": "Você apresentou a divergência com os dados necessários para uma decisão e esperou a atualização formal.",
              "example": null
            }
          ],
          "next": "preparar"
        },
        {
          "id": "aviso-vago",
          "text": "Enviar ao {{medico}} um aviso de que a dose parece incorreta, sem incluir o cálculo; aguardar resposta.",
          "quality": "weak",
          "replies": [
            {
              "from": "medico",
              "text": "Precisei abrir o registro para encontrar o peso de hoje e refazer a conta. Vou atualizar a prescrição; mantenha a dose em espera."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": 0
            },
            {
              "meter": "horario",
              "change": -20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "comunicacao",
              "kind": "improve",
              "text": "Você interrompeu o preparo, mas o aviso sem números exigiu uma nova busca. Inclua peso, cálculo, dose prescrita e via.",
              "example": "“São 18 kg; calculei 450 mg IV pelo plano, e a prescrição mostra 400 mg IV. Pode reavaliar?”"
            }
          ],
          "next": "preparar"
        }
      ]
    },
    {
      "id": "preparar",
      "messages": [
        {
          "from": "medico",
          "text": "Conferi o plano: mantenho 25 mg/kg/dose IV a cada 8 h. Atualizei e liberei a prescrição para 450 mg IV a cada 8 h."
        },
        {
          "from": "farmacia",
          "text": "O frasco preparado e identificado pela farmácia está rotulado como cefazolina 100 mg/mL. Confira esse rótulo antes de aspirar."
        },
        {
          "from": "enfermeira",
          "text": "Agora falta converter 450 mg em mL. Nossa rotina exige uma segunda conferência independente antes de administrar."
        }
      ],
      "prompt": "Como você prepara e confere a dose atualizada?",
      "choices": [
        {
          "id": "sem-segunda-checagem",
          "text": "Aspirar 4,5 mL, conferir o rótulo e administrar sem solicitar a segunda checagem.",
          "quality": "fair",
          "replies": [
            {
              "from": "enfermeira",
              "text": "O volume corresponde a 450 mg, mas faltou a conferência independente exigida pela clínica."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": -10
            },
            {
              "meter": "horario",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "calculo",
              "kind": "good",
              "text": "Você converteu corretamente 450 mg a 100 mg/mL em 4,5 mL.",
              "example": null
            },
            {
              "skill": "conferencia",
              "kind": "improve",
              "text": "A conferência do rótulo não substitui a segunda checagem independente prevista na rotina.",
              "example": null
            }
          ],
          "next": "sem-checagem"
        },
        {
          "id": "checar-em-dupla",
          "text": "Aspirar 4,5 mL e pedir à {{enfermeira}} uma conferência independente da prescrição, do rótulo, do cálculo e da via antes de administrar.",
          "quality": "strong",
          "replies": [
            {
              "from": "enfermeira",
              "text": "Minha conferência também deu 4,5 mL para 450 mg. A prescrição atualizada, o rótulo e a via IV conferem."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": 20
            },
            {
              "meter": "horario",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "calculo",
              "kind": "good",
              "text": "Você calculou o volume a partir da concentração indicada no rótulo.",
              "example": null
            },
            {
              "skill": "conferencia",
              "kind": "good",
              "text": "Você confirmou dose, concentração e via com uma segunda checagem independente antes da administração.",
              "example": null
            }
          ],
          "next": "administrado"
        },
        {
          "id": "volume-antigo",
          "text": "Usar 4,0 mL, volume anotado para a prescrição anterior, para não atrasar mais a dose.",
          "quality": "weak",
          "replies": [
            {
              "from": "enfermeira",
              "text": "Na revisão do registro, vi 4,0 mL administrados. A 100 mg/mL, isso corresponde a 400 mg. Vou comunicar a diferença ao plantão para avaliação."
            }
          ],
          "effects": [
            {
              "meter": "seguranca",
              "change": -30
            },
            {
              "meter": "horario",
              "change": 15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "calculo",
              "kind": "improve",
              "text": "O volume antigo não acompanha a prescrição atualizada: 4,0 mL contêm 400 mg nessa concentração. Refaça a conversão após toda mudança de dose.",
              "example": null
            },
            {
              "skill": "conferencia",
              "kind": "improve",
              "text": "Antes de administrar, compare o volume preparado com a prescrição vigente e peça a checagem independente.",
              "example": null
            }
          ],
          "next": "dose-antiga"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "administrado",
      "outcome": "A prescrição atualizada foi conferida de forma independente, e 4,5 mL da solução a 100 mg/mL forneceram os 450 mg IV previstos. A dúvida sobre o peso anterior foi resolvida antes da administração."
    },
    {
      "id": "sem-checagem",
      "outcome": "Foram administrados 450 mg IV, o equivalente a 4,5 mL da solução rotulada. A dose estava correta, mas a administração ficou sem a segunda checagem exigida pela clínica."
    },
    {
      "id": "dose-antiga",
      "outcome": "Foram administrados 4,0 mL, equivalentes a 400 mg, embora a prescrição atualizada indicasse 450 mg IV. A equipe identificou a diferença na revisão e a comunicou ao plantão para avaliação e registro."
    }
  ],
  "summary": [
    "Uma dose por peso deve ser recalculada com o peso atual e comparada com a prescrição vigente.",
    "Uma divergência de dose deve ser comunicada com peso, cálculo, prescrição e via, antes do preparo.",
    "Após uma mudança de dose, é preciso refazer a conversão em volume e cumprir a checagem independente prevista na rotina."
  ]
}

{
  "title": "What were Friday's sales?",
  "setting": "Friday at Cedar Cart",
  "mission": "Prepare **a trustworthy order count and sales total** from a messy checkout export. Tell the store lead which rows you changed and why.",
  "deadline": "Send the Friday report by 2 p.m.",
  "panels": [
    {
      "title": "Checkout export",
      "metrics": [
        {
          "label": "Rows",
          "value": "120",
          "note": null
        },
        {
          "label": "Exact duplicate rows",
          "value": "6",
          "note": "Each repeats an order ID."
        },
        {
          "label": "Blank order totals",
          "value": "4",
          "note": "All are on different orders."
        },
        {
          "label": "Rows labeled “web”",
          "value": "8",
          "note": "Other online rows say “Online.”"
        }
      ],
      "note": "The duplicate rows do not include the four blank totals or eight “web” rows."
    }
  ],
  "team": [
    {
      "id": "store",
      "role": "Store lead",
      "expertise": "Knows the checkout labels and needs the report today.",
      "ai": false
    },
    {
      "id": "records",
      "role": "Payment clerk",
      "expertise": "Can check missing amounts against the payment records.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Can flag rows, calculate totals, and show its changes.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "trust",
      "label": "Report reliability",
      "start": 55,
      "goodWhen": "high"
    },
    {
      "id": "time",
      "label": "Time left for the report",
      "start": 70,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "find",
      "name": "Find data problems",
      "practice": "Scan a small table for repeated IDs, blanks, and labels that might mean the same thing."
    },
    {
      "id": "clean",
      "name": "Clean data safely",
      "practice": "Write down which rows you would change, which you would leave alone, and why."
    },
    {
      "id": "check-ai",
      "name": "Check AI output",
      "practice": "Ask an AI assistant to show the source and calculation behind one changed value."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "store",
          "text": "The report is due soon. I need the order count and sales total, including online orders."
        },
        {
          "from": "ai",
          "text": "I can inspect the export and make a draft, but I don't know what every checkout label means."
        }
      ],
      "prompt": "How do you begin cleaning the export?",
      "choices": [
        {
          "id": "tag",
          "text": "Mark the duplicate rows and blank totals for review. Leave “web” unchanged for now.",
          "quality": "fair",
          "replies": [
            {
              "from": "store",
              "text": "Good call not to guess about “web.” I'll check the checkout guide."
            }
          ],
          "effects": [
            {
              "meter": "trust",
              "change": 8
            },
            {
              "meter": "time",
              "change": -8
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "find",
              "kind": "good",
              "text": "You marked the repeated rows and blanks instead of treating every row as a separate sale.",
              "example": null
            },
            {
              "skill": "clean",
              "kind": "improve",
              "text": "Confirm what “web” means before deciding how to count those orders.",
              "example": "“Can we check whether ‘web’ and ‘Online’ mean the same thing?”"
            }
          ],
          "next": "draft"
        },
        {
          "id": "verify",
          "text": "Ask {{ai}} to list the problem rows, and ask {{store}} what “web” means.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "I found six exact duplicate rows and four different orders with blank totals. I'll keep the original export untouched."
            },
            {
              "from": "store",
              "text": "I'll check the checkout guide before we group the labels."
            }
          ],
          "effects": [
            {
              "meter": "trust",
              "change": 15
            },
            {
              "meter": "time",
              "change": -10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "find",
              "kind": "good",
              "text": "You checked the different kinds of problems separately and sought a source for the unclear label.",
              "example": null
            },
            {
              "skill": "clean",
              "kind": "good",
              "text": "You kept the original export so changes can be checked later.",
              "example": null
            }
          ],
          "next": "draft"
        },
        {
          "id": "quick-copy",
          "text": "In a working copy, drop rows with blank totals and count “web” as Store to save time.",
          "quality": "weak",
          "replies": [
            {
              "from": "records",
              "text": "Those blank totals may still have payments. Please don't leave those orders out of the final count."
            }
          ],
          "effects": [
            {
              "meter": "trust",
              "change": -15
            },
            {
              "meter": "time",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "clean",
              "kind": "improve",
              "text": "A blank total does not mean the order never happened. Set it aside for checking rather than dropping it.",
              "example": null
            },
            {
              "skill": "find",
              "kind": "improve",
              "text": "Check an unfamiliar label before moving its rows into another group.",
              "example": "“What does ‘web’ mean in this checkout system?”"
            }
          ],
          "next": "draft"
        }
      ]
    },
    {
      "id": "draft",
      "messages": [
        {
          "from": "store",
          "text": "The checkout guide confirms that “web” and “Online” mean the same thing."
        },
        {
          "from": "ai",
          "text": "Using the original export, I removed six exact duplicate rows. The 110 orders with known totals add up to $5,500. I filled four blank totals with $50 each—the average of those 110—and drafted 114 orders and $5,700 in sales."
        }
      ],
      "prompt": "What do you do with the AI's draft?",
      "choices": [
        {
          "id": "use-estimate",
          "text": "Keep the $5,700 draft total; the average seems reasonable for four blanks.",
          "quality": "weak",
          "replies": [
            {
              "from": "records",
              "text": "I can still look up those four payments. An average is not the amount each customer paid."
            }
          ],
          "effects": [
            {
              "meter": "trust",
              "change": -20
            },
            {
              "meter": "time",
              "change": 2
            }
          ],
          "timeJump": {
            "label": "Ten minutes later",
            "panel": {
              "title": "Payment check",
              "metrics": [
                {
                  "label": "Known order totals",
                  "value": "$5,500",
                  "note": "110 orders after duplicates are removed."
                },
                {
                  "label": "Four recovered totals",
                  "value": "$195",
                  "note": "From payment records."
                },
                {
                  "label": "Verified sales total",
                  "value": "$5,695",
                  "note": "$5,500 + $195."
                }
              ],
              "note": "The payment clerk sent the records while the draft was being prepared."
            }
          },
          "notes": [
            {
              "skill": "check-ai",
              "kind": "improve",
              "text": "The AI clearly labeled its estimate, but an estimate should not replace amounts that can be checked.",
              "example": "“Can we find the four actual payments before using this total?”"
            }
          ],
          "next": "send"
        },
        {
          "id": "look-up",
          "text": "Ask {{ai}} to show its row changes and {{records}} to find the four actual payments.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "My change list shows six duplicate rows removed and four blanks filled with estimates. I can replace the estimates with recorded amounts."
            },
            {
              "from": "records",
              "text": "I'll check the four order IDs against the payment records."
            }
          ],
          "effects": [
            {
              "meter": "trust",
              "change": 20
            },
            {
              "meter": "time",
              "change": -15
            }
          ],
          "timeJump": {
            "label": "Ten minutes later",
            "panel": {
              "title": "Payment check",
              "metrics": [
                {
                  "label": "Known order totals",
                  "value": "$5,500",
                  "note": "110 orders after duplicates are removed."
                },
                {
                  "label": "Four recovered totals",
                  "value": "$195",
                  "note": "From payment records."
                },
